def u_getSubjectGrade(v_mark=None):
    v_num = None
    v_mark = f_trim(v_mark)
    if T((T((T(ident(v_mark, '')) or T(ident(v_mark, 'N/A')))) or T(ident(v_mark, 'ABSENT')))):
        return v_mark
